import { createGlobalStyle, } from "styled-components";

export const GlobalStyle = createGlobalStyle`
    html {
        box-sizing: border-box;
    }

    *,
    ::after,
    ::before {
        box-sizing: inherit;
    }

    body {
        background-color: ${( { theme }) => theme.color.liteSeaGreen };
        font-family: 'Poppins', sans-serif;
        margin: 0;
        padding: 0;
    }

`;