import { useState, useEffect } from "react";
import { useApiToSelectCountrys } from "../../API/useApiToSelectCountrys";
import { supabase } from "../../API/ApiKey";

export const useTeamForm = () => {

    const [team, setTeam] = useState('');
    const [country, setCountry] = useState('');
    const [error, setError] = useState(false);
    const [success, setSuccess] = useState(false);
    const [validationError, setValidationError] = useState('');
    const { teams } = useApiToSelectCountrys();

    useEffect(() => {
        if (success) {
            setTimeout(() => {
                window.location.reload();
            }, 2000);
        }
    }, [success]);

    const handleSubmit = async (e) => {
        e.preventDefault();

        const validationCountryName = country.replace(/[^a-zA-ZąćęłńóśźżĄĆĘŁŃÓŚŹŻ]/g, ' ').toLowerCase();
        const teamExists = teams.some((existingTeam) => existingTeam.country.toLowerCase() === validationCountryName.toLowerCase());
        const count = teams.filter((countTeam) => countTeam.team.toLowerCase() === team.toLowerCase()).length;
        const isLetter = (str) => /^[a-zA-Z]$/.test(str);

        setSuccess(false);

        if (!team || !country || validationCountryName === "") {
            setValidationError('Wszystkie pola muszą być wypełnione!');
            return;
        }

        if (teamExists) {
            setValidationError('Drużyna o tej nazwie kraju już istnieje!');
            return;
        }

        if (count >= 5) {
            setValidationError('Grupa już posiada 5 drużyn!');
            return;
        }

        if (isLetter(team) === false || team.length !== 1) {
            setValidationError('Grupa musi być literą, np: A!');
            return;
        }

        setValidationError('');

        const { data, error } = await supabase
            .from('teams')
            .insert([{
                team: team.toUpperCase(),
                country: validationCountryName.charAt(0).toUpperCase() + validationCountryName.slice(1),
            },
            ]);

        if (error) {
            setError(true);
        } else {
            setTeam('');
            setCountry('');
            setSuccess(true);
        }
    };

    return {
        team,
        setTeam,
        country,
        setCountry,
        error,
        success,
        handleSubmit,
        validationError,
    };
}